code_sketch:
protocol Shape { func area() -> Double }
struct Circle: Shape { let r: Double; func area() -> Double { .pi * r * r } }
struct Square: Shape { let side: Double; func area() -> Double { side * side } }

let shapes: [any Shape] = [Circle(r: 1), Square(side: 2)]   // one erased interface
shapes.reduce(0) { $0 + $1.area() }                         // witness-table dispatch

func makeShape() -> some Shape { Circle(r: 2) }              // static alternative: opaque type

